rimary","depth":"core"}]},{"code":"C2.04","position":10,"title":"Unit 2 · Lesson 4: Inverse Functions / Logarithmic Expressions (+1)","note":"Topics 2.8, 2.9, 2.10 · 5 sub-keywords (4 core, 1 light) · ~110 min · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"2","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"2.8","role":"primary","depth":"core"},{"contentCode":"2.9","role":"primary","depth":"core"},{"contentCode":"2.10","role":"primary","depth":"core"},{"contentCode":"2.8#1","role":"primary","depth":"core"},{"contentCode":"2.8#2","role":"primary","depth":"core"},{"contentCode":"2.9#1","role":"primary","depth":"core"},{"contentCode":"2.9#2","role":"primary","depth":"core"},{"contentCode":"2.10#1","role":"primary","depth":"light"}]},{"code":"C2.05","position":11,"title":"Unit 2 · Lesson 5: Inverses of Exponential Functions / Logarithmic Functions (+1)","note":"Topics 2.10, 2.11, 2.12 · 5 sub-keywords (4 core, 1 light) · ~110 min · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"2","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"2.10","role":"continued","depth":"core"},{"contentCode":"2.11","role":"primary","depth":"core"},{"contentCode":"2.12","role":"primary","depth":"core"},{"contentCode":"2.10#2","role":"primary","depth":"core"},{"contentCode":"2.11#1","role":"primary","depth":"core"},{"contentCode":"2.11#2","role":"primary","depth":"light"},{"contentCode":"2.12#1","role":"primary","depth":"core"},{"contentCode":"2.12#2","role":"primary","depth":"core"}]},{"code":"C2.06","position":12,"title":"Unit 2 · Lesson 6: Exponential and Logarithmic Equations and Inequalities / Logarithmic Function Context and Data Modeling (+1)","note":"Topics 2.13, 2.14, 2.15 · 6 sub-keywords (4 core, 2 light) · ~110 min · close with a short mixed MCQ+FRQ set for this unit · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"2","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"2.13","role":"primary","depth":"core"},{"contentCode":"2.14","role":"primary","depth":"core"},{"contentCode":"2.15","role":"primary","depth":"core"},{"contentCode":"2.13#1","role":"primary","depth":"core"},{"contentCode":"2.13#2","role":"primary","depth":"core"},{"contentCode":"2.14#1","role":"primary","depth":"core"},{"contentCode":"2.14#2","role":"primary","depth":"light"},{"contentCode":"2.15#1","role":"primary","depth":"light"},{"contentCode":"2.15#2","role":"primary","depth":"core"}]},{"code":"C3.01","position":13,"title":"Unit 3 · Lesson 1: Periodic Phenomena / Sine, Cosine, and Tangent (+1)","note":"Topics 3.1, 3.2, 3.3 · 5 sub-keywords (4 core, 1 light) · ~110 min · warm-up: Unit 2 mixed MCQ+FRQ retrieval · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"2.13","role":"review","depth":"core"},{"contentCode":"2.14","role":"review","depth":"core"},{"contentCode":"2.15","role":"review","depth":"core"},{"contentCode":"3.1","role":"primary","depth":"core"},{"contentCode":"3.2","role":"primary","depth":"core"},{"contentCode":"3.3","role":"primary","depth":"core"},{"contentCode":"3.1#1","role":"primary","depth":"core"},{"contentCode":"3.1#2","role":"primary","depth":"light"},{"contentCode":"3.2#1","role":"primary","depth":"core"},{"contentCode":"3.2#2","role":"primary","depth":"core"},{"contentCode":"3.3#1","role":"primary","depth":"core"}]},{"code":"C3.02","position":14,"title":"Unit 3 · Lesson 2: Sine and Cosine Function Values / Sine and Cosine Function Graphs (+1)","note":"Topics 3.3, 3.4, 3.5 · 5 sub-keywords (3 core, 2 light) · ~110 min · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.3","role":"continued","depth":"core"},{"contentCode":"3.4","role":"primary","depth":"core"},{"contentCode":"3.5","role":"primary","depth":"core"},{"contentCode":"3.3#2","role":"primary","depth":"core"},{"contentCode":"3.4#1","role":"primary","depth":"light"},{"contentCode":"3.4#2","role":"primary","depth":"core"},{"contentCode":"3.5#1","role":"primary","depth":"core"},{"contentCode":"3.5#2","role":"primary","depth":"light"}]},{"code":"C3.03","position":15,"title":"Unit 3 · Lesson 3: Sinusoidal Function Transformations / Sinusoidal Function Context and Data Modeling (+1)","note":"Topics 3.6, 3.7, 3.8 · 5 sub-keywords (4 core, 1 light) · ~110 min · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.6","role":"primary","depth":"core"},{"contentCode":"3.7","role":"primary","depth":"core"},{"contentCode":"3.8","role":"primary","depth":"core"},{"contentCode":"3.6#1","role":"primary","depth":"core"},{"contentCode":"3.6#2","role":"primary","depth":"core"},{"contentCode":"3.7#1","role":"primary","depth":"core"},{"contentCode":"3.7#2","role":"primary","depth":"core"},{"contentCode":"3.8#1","role":"primary","depth":"light"}]},{"code":"C3.04","position":16,"title":"Unit 3 · Lesson 4: The Tangent Function / Inverse Trigonometric Functions (+1)","note":"Topics 3.8, 3.9, 3.10 · 4 sub-keywords (4 core, 0 light) · ~110 min","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.8","role":"continued","depth":"core"},{"contentCode":"3.9","role":"primary","depth":"core"},{"contentCode":"3.10","role":"primary","depth":"core"},{"contentCode":"3.8#2","role":"primary","depth":"core"},{"contentCode":"3.9#1","role":"primary","depth":"core"},{"contentCode":"3.9#2","role":"primary","depth":"core"},{"contentCode":"3.10#1","role":"primary","depth":"core"}]},{"code":"C3.05","position":17,"title":"Unit 3 · Lesson 5: Trigonometric Equations and Inequalities / The Secant, Cosecant, and Cotangent Functions (+1)","note":"Topics 3.10, 3.11, 3.12 · 5 sub-keywords (4 core, 1 light) · ~110 min · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.10","role":"continued","depth":"core"},{"contentCode":"3.11","role":"primary","depth":"core"},{"contentCode":"3.12","role":"primary","depth":"core"},{"contentCode":"3.10#2","role":"primary","depth":"core"},{"contentCode":"3.11#1","role":"primary","depth":"core"},{"contentCode":"3.11#2","role":"primary","depth":"light"},{"contentCode":"3.12#1","role":"primary","depth":"core"},{"contentCode":"3.12#2","role":"primary","depth":"core"}]},{"code":"C3.06","position":18,"title":"Unit 3 · Lesson 6: Trigonometry and Polar Coordinates / Polar Function Graphs (+1)","note":"Topics 3.13, 3.14, 3.15 · 6 sub-keywords (4 core, 2 light) · ~110 min · close with a short mixed MCQ+FRQ set for this unit · light items: overview + worked example; drills in practice sets","kind":"content","unitCode":"3","estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.13","role":"primary","depth":"core"},{"contentCode":"3.14","role":"primary","depth":"core"},{"contentCode":"3.15","role":"primary","depth":"core"},{"contentCode":"3.13#1","role":"primary","depth":"core"},{"contentCode":"3.13#2","role":"primary","depth":"light"},{"contentCode":"3.14#1","role":"primary","depth":"light"},{"contentCode":"3.14#2","role":"primary","depth":"core"},{"contentCode":"3.15#1","role":"primary","depth":"core"},{"contentCode":"3.15#2","role":"primary","depth":"core"}]},{"code":"CX.1","position":19,"title":"Exam Prep 1: Cumulative review (first half) + Practice Exam 1 debrief","note":"Cumulative: Units 1–2 · ~110 min","kind":"exam_prep","unitCode":null,"estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"1.1","role":"review","depth":"core"},{"contentCode":"1.2","role":"review","depth":"core"},{"contentCode":"1.3","role":"review","depth":"core"},{"contentCode":"1.4","role":"review","depth":"core"},{"contentCode":"1.5","role":"review","depth":"core"},{"contentCode":"1.6","role":"review","depth":"core"},{"contentCode":"1.7","role":"review","depth":"core"},{"contentCode":"1.8","role":"review","depth":"core"},{"contentCode":"1.9","role":"review","depth":"core"},{"contentCode":"1.10","role":"review","depth":"core"},{"contentCode":"1.11","role":"review","depth":"core"},{"contentCode":"1.12","role":"review","depth":"core"},{"contentCode":"1.13","role":"review","depth":"core"},{"contentCode":"1.14","role":"review","depth":"core"},{"contentCode":"2.1","role":"review","depth":"core"},{"contentCode":"2.2","role":"review","depth":"core"},{"contentCode":"2.3","role":"review","depth":"core"},{"contentCode":"2.4","role":"review","depth":"core"},{"contentCode":"2.5","role":"review","depth":"core"},{"contentCode":"2.6","role":"review","depth":"core"},{"contentCode":"2.7","role":"review","depth":"core"},{"contentCode":"2.8","role":"review","depth":"core"},{"contentCode":"2.9","role":"review","depth":"core"},{"contentCode":"2.10","role":"review","depth":"core"},{"contentCode":"2.11","role":"review","depth":"core"},{"contentCode":"2.12","role":"review","depth":"core"},{"contentCode":"2.13","role":"review","depth":"core"},{"contentCode":"2.14","role":"review","depth":"core"},{"contentCode":"2.15","role":"review","depth":"core"}]},{"code":"CX.2","position":20,"title":"Exam Prep 2: Cumulative review (second half) + FRQ clinic and Practice Exam 2 debrief","note":"Cumulative: Units 3–3 · ~110 min","kind":"exam_prep","unitCode":null,"estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[{"contentCode":"3.1","role":"review","depth":"core"},{"contentCode":"3.2","role":"review","depth":"core"},{"contentCode":"3.3","role":"review","depth":"core"},{"contentCode":"3.4","role":"review","depth":"core"},{"contentCode":"3.5","role":"review","depth":"core"},{"contentCode":"3.6","role":"review","depth":"core"},{"contentCode":"3.7","role":"review","depth":"core"},{"contentCode":"3.8","role":"review","depth":"core"},{"contentCode":"3.9","role":"review","depth":"core"},{"contentCode":"3.10","role":"review","depth":"core"},{"contentCode":"3.11","role":"review","depth":"core"},{"contentCode":"3.12","role":"review","depth":"core"},{"contentCode":"3.13","role":"review","depth":"core"},{"contentCode":"3.14","role":"review","depth":"core"},{"contentCode":"3.15","role":"review","depth":"core"}]},{"code":"CX.3","position":21,"title":"Exam Prep 3: Final weak-area review and exam-day strategy","note":"Cumulative exam preparation · ~110 min","kind":"exam_prep","unitCode":null,"estMinutes":110,"lessonTrack":"core","scheduledMinutes":120,"links":[]}]}$seed$::jsonb;
  v_ed text := p #>> '{edition,edition}';
  v_sid uuid; v_cur text; v_name text := p #>> '{subject,name}'; v_code text := p #>> '{subject,apCode}';
  v_track text := p ->> 'track';
  v_max int; v_tail int; v_pos int; v_id uuid; v_title text; r record; l jsonb; u jsonb; lvl int;
  v_taken int[]; v_plan_ids uuid[] := '{}'; v_drop uuid[]; v_keep uuid[];
  v_plan_codes text[] := array(select x->>'code' from jsonb_array_elements(p->'lessons') x);
  v_unit_codes text[] := array(select x->>'code' from jsonb_array_elements(p->'units') x);
begin
  -- 과목
  select id, ap_subject_code into v_sid, v_cur from subjects where name = v_name;
  if found then
    if v_cur is not null and v_cur <> v_code then raise exception '과목 % 의 ap_subject_code 충돌', v_name; end if;
    if v_cur is null then update subjects set ap_subject_code = v_code where id = v_sid; end if;
  else
    insert into subjects (name, ap_subject_code) values (v_name, v_code) returning id into v_sid;
  end if;

  -- 판 / 스킬 / 비중
  insert into ap_curriculum_editions (subject_id, edition, ced_version, source_url, exam_year, family, official_topic_codes, design_notes, is_current)
  values (v_sid, v_ed, p #>> '{edition,cedVersion}', p #>> '{edition,sourceUrl}', (p #>> '{edition,examYear}')::int, p #>> '{edition,family}', (p #>> '{edition,officialTopicCodes}')::boolean, p #>> '{edition,designNotes}', true)
  on conflict (subject_id, edition) do update set ced_version = excluded.ced_version, source_url = excluded.source_url, exam_year = excluded.exam_year, family = excluded.family,
    official_topic_codes = excluded.official_topic_codes, design_notes = excluded.design_notes, is_current = excluded.is_current;
  insert into ap_skills (subject_id, edition, code, category, label, sort_order)
  select v_sid, v_ed, k->>'code', k->>'category', k->>'label', (k->>'sort')::int from jsonb_array_elements(p->'skills') k
  on conflict (subject_id, edition, code) do update set category = excluded.category, label = excluded.label, sort_order = excluded.sort_order;
  insert into ap_exam_weights (subject_id, edition, axis, code, section, min_pct, max_pct, source)
  select v_sid, v_ed, k->>'axis', k->>'code', k->>'section', (k->>'min')::numeric, (k->>'max')::numeric, k->>'source' from jsonb_array_elements(p->'weights') k
  on conflict (subject_id, edition, axis, code, section) do update set min_pct = excluded.min_pct, max_pct = excluded.max_pct, source = excluded.source;

  -- 단원 = 키워드 폴더(이미 있으면 그대로)
  insert into subject_keyword_folders (subject_id, name, position, official_code, source)
  select v_sid, k->>'name', (k->>'position')::int, k->>'code', 'ced' from jsonb_array_elements(p->'units') k
  where not exists (select 1 from subject_keyword_folders f where f.subject_id = v_sid and f.official_code = k->>'code');

  -- 키워드: 기존 코드는 메타만 갱신(이름·폴더 불변), 새 코드는 토픽 → 세부 순으로 생성
  update subject_keywords sk set skill_codes = array(select jsonb_array_elements_text(k->'skillCodes')), requires_codes = array(select jsonb_array_elements_text(k->'requiresCodes')), est_lessons = (k->>'estLessons')::numeric,
    kind = k->>'kind', scope = k->>'scope', content_key = k->>'contentKey', sort_order = (k->>'sortOrder')::int
  from jsonb_array_elements(p->'keywords') k where sk.subject_id = v_sid and sk.content_code = k->>'contentCode';
  for lvl in 1..2 loop
    insert into subject_keywords (subject_id, label, status, content_code, content_key, level, parent_keyword_id, source, edition, kind, skill_codes, requires_codes, est_lessons, scope, folder_id, sort_order)
    select v_sid, k->>'label', 'active'::keyword_status, k->>'contentCode', k->>'contentKey', lvl,
      (select x.id from subject_keywords x where x.subject_id = v_sid and x.content_code = k->>'parentCode'), 'ced', v_ed, k->>'kind',
      array(select jsonb_array_elements_text(k->'skillCodes')), array(select jsonb_array_elements_text(k->'requiresCodes')), (k->>'estLessons')::numeric, k->>'scope',
      (select f.id from subject_keyword_folders f where f.subject_id = v_sid and f.official_code = k->>'unitCode'), (k->>'sortOrder')::int
    from jsonb_array_elements(p->'keywords') k
    where (k->>'level')::int = lvl and not exists (select 1 from subject_keywords x where x.subject_id = v_sid and x.content_code = k->>'contentCode')
    order by (k->>'sortOrder')::int;
  end loop;

  -- 회차(템플릿 행)
  select coalesce(max(position), 0) into v_max from subject_template_units where subject_id = v_sid;
  -- 이전 시드의 단원 단위 행 정리(source='ced', lesson_kind null, 단원 번호 코드)
  delete from subject_template_units where subject_id = v_sid and lesson_kind is null and official_code = any (v_unit_codes) and source = 'ced';
  -- 다른 과정 회차: 참조 없으면 삭제, 참조되면 보존하고 primary → review 강등 + 순서 뒤로
  select coalesce(array_agg(id), '{}') into v_drop from subject_template_units t
   where t.subject_id = v_sid and t.lesson_kind is not null and t.official_code is not null and t.official_code <> all (v_plan_codes)
     and not exists (select 1 from curriculum_overlay_units o where o.source_unit_id = t.id)
     and not exists (select 1 from teacher_curriculum_template_units o where o.source_unit_id = t.id);
  select coalesce(array_agg(id order by position), '{}') into v_keep from subject_template_units t
   where t.subject_id = v_sid and t.lesson_kind is not null and t.official_code is not null and t.official_code <> all (v_plan_codes) and t.id <> all (v_drop);
  delete from subject_template_units where id = any (v_drop) and source = 'ced';
  if cardinality(v_keep) > 0 then
    update subject_template_unit_keywords set role = 'review' where unit_id = any (v_keep) and role = 'primary';
    v_tail := v_max + 10000;
    foreach v_id in array v_keep loop v_tail := v_tail + 1; update subject_template_units set position = v_tail where id = v_id; end loop;
    raise notice '참조 중이라 보존한 다른 과정 회차 % 개', cardinality(v_keep);
  end if;
  -- 위치 충돌 계산: 남은 행(보존분은 +10000 이상으로 이동됨, 삭제분 제외)
  select coalesce(array_agg(position), '{}') into v_taken from subject_template_units where subject_id = v_sid;
  for l in select x from jsonb_array_elements(p->'lessons') x loop
    select id, unit_title into v_id, v_title from subject_template_units where subject_id = v_sid and official_code = l->>'code';
    if found then
      update subject_template_units set lesson_kind = l->>'kind', ced_unit_code = l->>'unitCode', est_minutes = (l->>'estMinutes')::int, track = l->>'lessonTrack', track_set = v_track,
        scheduled_minutes = (l->>'scheduledMinutes')::int, suggested_lessons = 1, note = l->>'note',
        unit_title = case when v_title is null or v_title = '' or v_title ~ '^Unit [0-9]+ · Lesson |^Exam Prep ' then l->>'title' else unit_title end
      where id = v_id;
    else
      v_pos := (l->>'position')::int;
      while v_pos = any (v_taken) loop v_pos := v_pos + 1000; end loop;
      v_taken := v_taken || v_pos;
      insert into subject_template_units (subject_id, position, unit_title, note, official_code, source, lesson_kind, ced_unit_code, est_minutes, track, track_set, scheduled_minutes, suggested_lessons)
      values (v_sid, v_pos, l->>'title', l->>'note', l->>'code', 'ced', l->>'kind', l->>'unitCode', (l->>'estMinutes')::int, l->>'lessonTrack', v_track, (l->>'scheduledMinutes')::int, 1);
    end if;
  end loop;
  -- 재시드: 계획 회차의 기존 연결을 비우고 새 계획으로 다시 만든다
  delete from subject_template_unit_keywords where unit_id in (select id from subject_template_units where subject_id = v_sid and official_code = any (v_plan_codes));
  insert into subject_template_unit_keywords (unit_id, keyword_id, role, depth)
  select t.id, kw.id, lk->>'role', lk->>'depth'
  from jsonb_array_elements(p->'lessons') l2
  cross join lateral jsonb_array_elements(l2->'links') lk
  join subject_template_units t on t.subject_id = v_sid and t.official_code = l2->>'code'
  join subject_keywords kw on kw.subject_id = v_sid and kw.content_code = lk->>'contentCode'
  on conflict (unit_id, keyword_id) do update set role = excluded.role, depth = excluded.depth;
  if (select count(*) from subject_template_unit_keywords k join subject_template_units t on t.id = k.unit_id where t.subject_id = v_sid and t.official_code = any (v_plan_codes))
     < (select count(*) from jsonb_array_elements(p->'lessons') l3, jsonb_array_elements(l3->'links') lk3) then
    raise exception '회차 연결 대상 id 누락';
  end if;
end
$do$;
commit;
